  }

  Object? lookup(AppLocalizationsKey key) {
    return lookupKey(key.rawKey,
        arguments: key.arguments, namedArguments: key.namedArguments);
  }

  String parseKey(AppLocalizationsKey key) {
    final result = lookup(key);
    if (result == null) {
      return 'Translation key not found!';
    }
    return result as String;
  }

  String parseL10n(String translationKey,
      {List<Object>? arguments, Map<String, Object?>? namedArguments}) {
    final result = lookupKey(translationKey,
        arguments: arguments, namedArguments: namedArguments);
    if (result == null) {
      return 'Translation key not found!';
    }
    return result as String;
  }
}
